public class NewtonRaphson {
  // Para Java, programarías la lógica matemática de derivada de Newton:
  public static double eqn(double x) { return x + Math.cos(x); }
  public static double deriv(double x) { return 1 - Math.sin(x); }

  public static void main(String[] args) {
      double h = 0;
      double x = 0;
      // Iterar para encontrar la convergencia:
      for (int i = 0; i < 50; i++) {
          h = eqn(x) / deriv(x);
          x = x - h;
      }
      System.out.println(x);
  }
}
